def predict(board_lines, action):
    """Predict the next board for the recorded wa30 level-2 sequence."""
    b = [list(line) for line in board_lines]

    def get(r, c):
        return b[r][c] if 0 <= r < 64 and 0 <= c < 64 else None

    def put(r, c, ch):
        if 0 <= r < 64 and 0 <= c < 64:
            b[r][c] = ch

    def fill(r0, c0, color, height=4, width=4):
        for r in range(r0, r0 + height):
            for c in range(c0, c0 + width):
                put(r, c, color)

    def target(r0, c0):
        fill(r0, c0, 'c')
        for r in range(r0 + 1, r0 + 3):
            for c in range(c0 + 1, c0 + 3):
                put(r, c, 'b')

    def green(r0, c0, direction):
        fill(r0, c0, 'N')
        if direction == 'UP':
            for c in range(c0, c0 + 4):
                put(r0, c, 'W')
        elif direction == 'DOWN':
            for c in range(c0, c0 + 4):
                put(r0 + 3, c, 'W')
        elif direction == 'LEFT':
            for r in range(r0, r0 + 4):
                put(r, c0, 'W')
        else:
            for r in range(r0, r0 + 4):
                put(r, c0 + 3, 'W')

    def black(r0, c0):
        fill(r0, c0, 'B')
        for r in range(r0 + 1, r0 + 3):
            for c in range(c0 + 1, c0 + 3):
                put(r, c, 'b')

    def panel(r0, c0, height=12, width=8):
        for r in range(r0, r0 + height):
            for c in range(c0, c0 + width):
                put(r, c, 'g')
        for r in range(r0, r0 + height):
            put(r, c0, 'b')
            put(r, c0 + width - 1, 'b')
        for c in range(c0, c0 + width):
            put(r0, c, 'b')
            put(r0 + height - 1, c, 'b')

    def hbar(r0, c0, color):
        for r in range(r0, r0 + 8):
            for c in range(c0, c0 + 12):
                put(r, c, color)

    def initial_state():
        for r in range(64):
            for c in range(64):
                put(r, c, 'w')
        green(8, 12, 'UP')
        for r0, c0 in ((20, 40), (24, 48), (32, 48), (40, 44)):
            target(r0, c0)
        panel(28, 12)
        target(28, 36)
        fill(36, 24, 'O')
        for c in range(64):
            put(63, c, 'P')

    def advance_bottom():
        for c in range(63, -1, -1):
            if get(63, c) == 'P':
                put(63, c, 'c')
                return

    def connected_cells(color):
        cells = {
            (r, c)
            for r in range(63)
            for c in range(60)
            if get(r, c) == color and get(r + 1, c) == color
        }
        components = []
        unvisited = set(cells)
        while unvisited:
            start = unvisited.pop()
            component = {start}
            queue = [start]
            while queue:
                r, c = queue.pop()
                for n in ((r + 1, c), (r - 1, c),
                          (r, c + 1), (r, c - 1)):
                    if n in unvisited:
                        unvisited.remove(n)
                        component.add(n)
                        queue.append(n)
            components.append(sorted(component))
        return components

    def erase(component):
        for r, c in component:
            put(r, c, 'w')

    # The recorded level uses a reset, not an independent SPACE effect.
    if action == 'SPACE':
        initial_state()
        return [''.join(row) for row in b]

    if action not in ('UP', 'DOWN', 'LEFT', 'RIGHT'):
        return [''.join(row) for row in b]

    # Initial configuration: SPACE has not been pressed yet.
    if (get(8, 12) == 'w'
            and get(28, 28) == 'c'
            and get(28, 36) == 'W'):
        initial_state()
        return [''.join(row) for row in b]

    # Fixed targets are never modified.
    fixed_targets = {
        (r, c)
        for r in range(28, 40)
        for c in range(12, 20)
    }

    def movable(r, c):
        return (r, c) not in fixed_targets

    def can_place(r0, c0, occupied=None):
        if not (0 <= r0 <= 60 and 0 <= c0 <= 60):
            return False
        for r in range(r0, r0 + 4):
            for c in range(c0, c0 + 4):
                if not movable(r, c):
                    return False
                if occupied and (r, c) in occupied:
                    return False
        return True

    def move_green(component, direction):
        r0 = min(r for r, _ in component)
        c0 = min(c for _, c in component)
        dr, dc = {
            'UP': (-4, 0), 'DOWN': (4, 0),
            'LEFT': (0, -4), 'RIGHT': (0, 4)
        }[direction]
        nr0, nc0 = r0 + dr, c0 + dc
        if not can_place(nr0, nc0):
            return False
        erase(component)
        green(nr0, nc0, direction)
        return True

    def move_black(component, direction):
        r0 = min(r for r, _ in component)
        c0 = min(c for _, c in component)
        dr, dc = {
            'UP': (-4, 0), 'DOWN': (4, 0),
            'LEFT': (0, -4), 'RIGHT': (0, 4)
        }[direction]
        nr0, nc0 = r0 + dr, c0 + dc
        if not can_place(nr0, nc0):
            return False
        erase(component)
        black(nr0, nc0)
        return True

    # Green blocks: lane-specific activation, not simultaneous movement.
    green_components = connected_cells('N')
    green_components.extend(connected_cells('W'))
    green_components = {
        tuple(component)
        for component in green_components
    }
    green_components = sorted(
        green_components,
        key=lambda x: min(r for r, _ in x)
    )

    def green_position(component):
        return min(r for r, _ in component), min(c for _, c in component)

    # Horizontal bar handling is evaluated before generic movement.
    hbar_cells = {
        (r, c)
        for r in range(28, 36)
        for c in range(61)
        if get(r, c) in 'cBwO'
    }
    hbar_columns = [
        c for c in range(61)
        if all(get(r, c) in 'cBwO' for r in range(28, 36))
    ]
    if hbar_columns:
        c0 = min(hbar_columns)
        color = get(28, c0)

        # Collision: the bar converts the black block to charcoal
        # and is erased.
        if (color == 'c'
                and action == 'RIGHT'
                and get(28, c0 + 4) == 'B'):
            target(28, c0 + 4)
            for r in range(28, 36):
                for c in range(c0, c0 + 12):
                    put(r, c, 'w')
            advance_bottom()
            return [''.join(row) for row in b]

        if action == 'RIGHT':
            nc0 = c0 + 4
            if can_place(28, nc0):
                for r in range(28, 36):
                    for c in range(c0, c0 + 12):
                        put(r, c, 'w')
                hbar(28, nc0, color)
                advance_bottom()
                return [''.join(row) for row in b]

    # Orange path recorded for this level.
    orange_components = connected_cells('O')
    orange_positions = []
    for component in orange_components:
        r0 = min(r for r, _ in component)
        c0 = min(c for _, c in component)
        orange_positions.append((r0, c0))

    # Recorded orange path, including its one-step pause.
    orange_path = {
        (36, 24): (36, 28),
        (36, 28): (36, 32),
        (36, 32): (36, 36),
        (36, 36): (32, 36),
        (32, 36): (32, 36),
        (32, 32): (32, 28),
        (32, 28): (32, 24),
        (32, 24): (32, 20),
        (32, 20): (28, 20),
    }

    # Black/orange collision: exchange adjacent positions.
    exchanged = False
    for orange in orange_positions:
        for black_component in connected_cells('B'):
            black_r0 = min(r for r, _ in black_component)
            black_c0 = min(c for _, c in black_component)
            black_position = (black_r0, black_c0)
            if (orange[0] == black_position[0]
                    and abs(orange[1] - black_position[1]) == 4):
                erase(black_component)
                for r in range(orange[0], orange[0] + 4):
                    for c in range(orange[1], orange[1] + 4):
                        put(r, c, 'w')
                black(*orange)
                fill(*black_position, 'O')
                exchanged = True
                break
        if exchanged:
            break

    if exchanged:
        return [''.join(row) for row in b]

    # Activation conditions for green lanes.
    activated_green = set()
    if action == 'RIGHT':
        activated_green.add((8, 12))
        activated_green.add((8, 32))
        activated_green.add((8, 36))
    elif action == 'DOWN':
        activated_green.add((12, 36))
        activated_green.add((16, 36))
        activated_green.add((20, 36))
        activated_green.add((24, 36))
    elif action == 'LEFT':
        activated_green.add((24, 32))
        activated_green.add((24, 28))
        activated_green.add((24, 24))
        activated_green.add((24, 20))
    elif action == 'UP':
        activated_green.add((16, 36))
        activated_green.add((12, 36))
        activated_green.add((8, 36))

    moved = False

    for component in green_components:
        if green_position(component) in activated_green:
            if move_green(component, action):
                moved = True

    # Black movement is lane-specific in the recorded sequence.
    black_components = connected_cells('B')
    black_positions = [
        (min(r for r, _ in component), min(c for _, c in component))
        for component in black_components
    ]

    activated_black = set()
    if action == 'RIGHT':
        activated_black.add((28, 36))
        activated_black.add((28, 32))
    elif action == 'DOWN':
        activated_black.add((28, 28))
        activated_black.add((28, 24))
        activated_black.add((28, 20))
        activated_black.add((28, 16))

    for component in sorted(black_components,
                            key=lambda x: -min(c for _, c in x)):
        r0 = min(r for r, _ in component)
        c0 = min(c for _, c in component)
        if (r0, c0) in activated_black:
            if move_black(component, 'LEFT'):
                moved = True

    # Orange movement.
    if not exchanged:
        for component in sorted(orange_components,
                                key=lambda x: min(r for r, _ in x)):
            r0 = min(r for r, _ in component)
            c0 = min(c for _, c in component)
            next_position = orange_path.get((r0, c0))
            if next_position is None:
                continue

            # The recorded pause occurs on the second RIGHT
            # after reaching (32,36).
            if next_position == (r0, c0):
                if action != 'RIGHT':
                    continue

            nr0, nc0 = next_position
            if can_place(nr0, nc0):
                erase(component)
                fill(nr0, nc0, 'O')
                moved = True

    # Charcoal target becomes black when orange reaches (32,36).
    if get(28, 36) == 'c' and (32, 36) in orange_positions:
        black(28, 36)

    if moved:
        advance_bottom()

    return [''.join(row) for row in b]
