                r"MOUSE\s*\(\s*(\d+)\s*,\s*(\d+)\s*\)",
                a,
                re.I,
            )
            if m:
                return int(m.group(1)), int(m.group(2))
        elif isinstance(a, (tuple, list)):
            if len(a) == 3 and str(a[0]).upper() == "MOUSE":
