def predict(board_lines, action):
    import re

    b = [list(row) for row in board_lines]

    def parse_mouse(value):
        if isinstance(value, str):
            nums = re.findall(r"-?\d+", value)
            if len(nums) >= 2:
                return int(nums[0]), int(nums[1])
            if len(nums) == 1:
                return int(nums[0]), None
        elif isinstance(value, (tuple, list)) and len(value) >= 2:
            return int(value[0]), int(value[1])
        return None

    def action_name(value):
        if isinstance(value, str):
            return value.strip().upper()
        if isinstance(value, (tuple, list)) and value:
            return str(value[0]).strip().upper()
        return str(value).strip().upper()

    def is_initial_setup():
        return (
            len(b) >= 64
            and all(len(b[r]) >= 64 for r in range(64))
            and b[0][16] == "W"
            and b[14][26] == "b"
        )

    def occupied_positions():
        occupied = []
        for r in range(1, 61):
            for c in range(1, 61):
                if b[r][c] not in ("b", "c", "p", "W"):
                    occupied.append((r, c))

        if not occupied:
            return []

        yellow = [p for p in occupied if b[p[0]][p[1]] == "Y"]
        if not yellow:
            return []

        y0, x0 = min(yellow, key=lambda p: (p[0], p[1]))
        return [
            ((r - y0) // 3, (c - x0) // 3)
            for r, c in occupied
        ]

    def infer_orientation():
        occupied = occupied_positions()
        if not occupied:
            return 0

        candidates = set()
        for orientation, offsets in ORIENTATIONS.items():
            if set(offsets) == set(occupied):
                candidates.add(orientation)

        if candidates:
            return min(candidates)
        return 0

    def render_assembly(y, x, orientation):
        for dr, dc in ORIENTATIONS[orientation]:
            r = y + 3 * dr
            c = x + 3 * dc
            for rr in range(r, r + 3):
                for cc in range(c, c + 3):
                    if 0 <= rr < 64 and 0 <= cc < 64:
                        b[rr][cc] = "Y" if (dr, dc) == (0, 0) else "R"

    ORIENTATIONS = {
        0: ((0, 0), (0, 1), (3, 0)),
        1: ((0, 0), (1, -1), (2, 0)),
        2: ((1, 0), (0, 1), (2, 0)),
        3: ((1, 0), (0, -1), (2, 0)),
    }

    SLOTS = {
        (14, 26),
        (5, 53),
        (38, 5),
        (47, 47),
    }

    def clear_assembly():
        for r in range(1, 61):
            for c in range(1, 61):
                if b[r][c] not in ("b", "c", "p", "W"):
                    b[r][c] = "p"

    def move_assembly(dr, dc):
        occupied = []
        for r in range(1, 61):
            for c in range(1, 61):
                if b[r][c] not in ("b", "c", "p", "W"):
                    occupied.append((r, c))

        if not occupied:
            return

        yellow = [p for p in occupied if b[p[0]][p[1]] == "Y"]
        if not yellow:
            return

        y, x = min(yellow, key=lambda p: (p[0], p[1]))
        orientation = infer_orientation()

        clear_assembly()
        render_assembly(y + dr, x + dc, orientation)

    def advance_counter():
        for c in range(16, 24):
            if b[0][c] == "W":
                b[0][c] = "c"
                b[0][min(c + 1, 23)] = "W"
                return

    name = action_name(action)

    if name == "LEFT":
        if is_initial_setup():
            for r in range(16):
                for c in range(64):
                    b[r][c] = "p"

            for c in range(16, 24):
                b[0][c] = "c"

            for r in range(5, 8):
                for c in range(53, 56):
                    b[r][c] = "R"

            for r in range(41, 44):
                for c in range(5, 8):
                    b[r][c] = "O"

            render_assembly(14, 26, 0)

        else:
            occupied = []
            for r in range(1, 61):
                for c in range(1, 61):
                    if b[r][c] not in ("b", "c", "p", "W"):
                        occupied.append((r, c))

            yellow = [p for p in occupied if b[p[0]][p[1]] == "Y"]
            if yellow:
                y, x = min(yellow, key=lambda p: (p[0], p[1]))
                orientation = infer_orientation()
                clear_assembly()
                render_assembly(y, x, (orientation - 1) % 4)

    elif name == "SPACE":
        occupied = []
        for r in range(1, 61):
            for c in range(1, 61):
                if b[r][c] not in ("b", "c", "p", "W"):
                    occupied.append((r, c))

        yellow = [p for p in occupied if b[p[0]][p[1]] == "Y"]
        if yellow:
            y, x = min(yellow, key=lambda p: (p[0], p[1]))
            displacement = {
                (14, 26): (0, -3),
                (38, 5): (0, 3),
                (47, 47): (-3, 0),
                (5, 53): (0, 3),
            }.get((y, x))

            if displacement is not None:
                move_assembly(*displacement)

    elif name == "UP":
        move_assembly(-3, 0)

    elif name == "MOUSE":
        mouse = parse_mouse(action)
        if mouse is not None:
            r, c = mouse
            if (r, c) in SLOTS:
                orientation = infer_orientation()
                clear_assembly()
                render_assembly(r, c, orientation)

    # The supplied data does not establish a general counter-timing rule.
    if name in ("LEFT", "SPACE", "MOUSE"):
        advance_counter()

    return ["".join(row) for row in b]
