                return str(value[0]), int(value[1]), int(value[2])
            if len(value) == 2:
                return "MOUSE", int(value[0]), int(value[1])
        if isinstance(value, str):
            match = re.fullmatch(
                r"(?:MOUSE)?\s*\(?\s*(\d+)\s*,\s*(\d+)\s*\)?",
                value.strip(),
                re.IGNORECASE,
            )
            if match:
                return "MOUSE", int(match.group(1)), int(match.group(2))
        return None

    def normalize_action(value):
        if isinstance(value, (tuple, list)):
            if value:
                name = str(value[0]).strip().upper()
                if name == "MOUSE":
                    return parse_mouse(value)
                return name
            return ""

        if isinstance(value, str):
            name = value.strip().upper()
            if name.startswith("MOUSE"):
                return parse_mouse(value)
            return name

        return str(value).strip().upper()

    action = normalize_action(action)

    if not isinstance(board_lines, (list, tuple)) or len(board_lines) != 64:
        raise ValueError("Expected 64 board lines.")

